const isDistrictLife=(station,key)=>!!stationDailyLines[station]?.[key];
function makeDistrictPlan(s){if(districtPlans[s.id])return districtPlans[s.id];return {name:s.desc,sky:'#728aa0',ground:'#5b7767',spots:[['station','🚉','駅の改札','车站·交通','train',25,29],['main','🏬',sc(s.sid)?.n||'駅前の店',s.desc,s.sid,74,29],['market','🏪','商店街','购物·便利店','conv',25,70],['help','🗺','案内所','问路·应急','help',74,70]],npc:['街区向导',s.jp+'駅へようこそ！','车站、商店和问路处都在附近。']}}
let district=null,districtPos={x:50,y:51},districtTarget=null,districtDialog=0;
function districtBackdrop(plan,station){let accent=station.id==='shibuya'?'#e4a77d':station.id==='akihabara'?'#bd91d6':station.id==='shinjuku'?'#d3a19a':'#d2bb8a';
let out=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 288" preserveAspectRatio="none" aria-label="${station.jp}像素街区地图" role="img"><defs><pattern id="districtTiles" width="16" height="16" patternUnits="userSpaceOnUse"><rect width="16" height="16" fill="${plan.ground}"/><path d="M0 15H16M15 0V16" stroke="#2e5147" stroke-width="1" opacity=".25"/><rect x="3" y="5" width="3" height="3" fill="#86a77c" opacity=".5"/></pattern></defs><rect width="320" height="288" fill="url(#districtTiles)"/><path d="M128 0H193V288H128Z" fill="#a89c8c"/><path d="M0 120H320V165H0Z" fill="#b3a799"/><path d="M153 0V288M168 0V288M0 141H320" stroke="#eee1b6" stroke-width="2" stroke-dasharray="8 9" opacity=".6"/>`;
for(const [i,sp] of plan.spots.entries()){if(sp[4]==='__life__')continue;let x=sp[5]*3.2,y=sp[6]*2.88;let w=80,h=65;let left=x-w/2,top=y-h/2;out+=`<rect x="${left+4}" y="${top+9}" width="${w}" height="${h}" fill="#203746"/><rect x="${left}" y="${top}" width="${w}" height="${h-9}" fill="${accent}"/><rect x="${left-3}" y="${top}" width="${w+6}" height="11" fill="${i%2?'#593f60':'#604c4a'}"/><rect x="${left+8}" y="${top+21}" width="18" height="17" fill="#344e66"/><rect x="${left+54}" y="${top+21}" width="18" height="17" fill="#344e66"/><rect x="${left+32}" y="${top+27}" width="17" height="${h-36}" fill="#4b5364"/>`;}
for(let k=0;k<14;k++){let x=8+(k*67)%305,y=12+(k*43)%275;if(x>130&&x<192)continue;out+=`<rect x="${x}" y="${y}" width="5" height="7" fill="#315649" opacity=".7"/>`}
return out+'<rect x="120" y="132" width="79" height="25" fill="#d0c2aa" opacity=".2"/></svg>'}
function enterDistrict(id){const s=byId[id];if(!s)return;district=s;districtPos={x:50,y:51};districtTarget=null;districtDialog=0;activeStation=s.jp;progress.visits[id]=(progress.visits[id]||0)+1;save();renderDistrict();}
function moveDistrict(dx,dy){if(!district)return;districtPos.x=Math.max(10,Math.min(90,districtPos.x+dx));districtPos.y=Math.max(12,Math.min(88,districtPos.y+dy));renderDistrictPosition();const plan=makeDistrictPlan(district);const near=plan.spots.find(sp=>Math.abs(sp[5]-districtPos.x)<12&&Math.abs(sp[6]-districtPos.y)<12);if(near&&(!districtTarget||districtTarget[0]!==near[0]))selectSpot(near[0]);}
function renderDistrictPosition(){let p=document.getElementById('district-player');if(p){p.style.left=districtPos.x+'%';p.style.top=districtPos.y+'%'}}
function selectSpot(id){const plan=makeDistrictPlan(district),spot=plan.spots.find(sp=>sp[0]===id);if(!spot)return;districtTarget=spot;districtDialog=0;
 if(isDistrictLife(district.id,id)){
   progress.cityLife??={};progress.cityLife[district.id]??={};progress.cityLife[district.id][id]=(progress.cityLife[district.id][id]||0)+1;save();
   const box=document.getElementById('district-chat');box.replaceChildren();
   const title=document.createElement('strong');title.textContent=spot[1]+' '+spot[2];box.appendChild(title);
   const p=document.createElement('p');p.textContent=stationDailyLines[district.id][id];box.appendChild(p);
   const b=document.createElement('button');b.className='rpg-action';b.textContent='继续逛街';b.onclick=()=>{box.replaceChildren();const msg=document.createElement('p');msg.textContent='你继续沿街走去。';box.appendChild(msg)};box.appendChild(b);return;
 }
 document.getElementById('district-chat').innerHTML=`<strong>▶ ${spot[2]}</strong><p>${spot[3]}。办事前需要与这里的人交谈。</p><button class="rpg-action primary" id="district-start" style="width:100%">进入 ${spot[2]} · 开始交谈</button>`;document.getElementById('district-start').onclick=()=>{activeStation=district.jp+' / '+spot[2];start(spot[4]);};}
function talkToNPC(){let plan=makeDistrictPlan(district);districtTarget=null;let lines=[plan.npc[1],plan.npc[2],'走到地图上的建筑旁，可以进店办事。也可以用 WASD 移动角色，靠近建筑触发任务。'];let i=districtDialog%lines.length;document.getElementById('district-chat').innerHTML=`<strong>💬 ${plan.npc[0]}</strong><p>${esc(DISTORT.text(lines[i]))}</p><button class="rpg-action" id="district-next" style="width:100%">${i===lines.length-1?'再次对话':'继续对话 ▶'}</button>`;document.getElementById('district-next').onclick=()=>{districtDialog++;talkToNPC()};}
function renderDistrict(){const s=district,plan=makeDistrictPlan(s);app.innerHTML=`<div class="rpg-shell"><section class="rpg-panel"><div class="district-top"><div><div class="rpg-kicker">TOKYO / STATION EXPLORATION</div><h1>${['haneda','narita','disney'].includes(s.id)?'🗺':'🚉'} ${s.jp}${['haneda','narita','disney'].includes(s.id)?'':'駅'}</h1><div class="rpg-tiny">${plan.name} · 像素街区</div></div><button class="rpg-inline-back" id="district-back">← 东京地图</button></div><div class="district-hud"><span>🧭 ${s.jp} · EXPLORING</span><span>${V51.languageLabel()} · 理解度 ${V51.language().xp}</span></div><div class="district-world" id="district-world">${districtBackdrop(plan,s)}${plan.spots.map(sp=>`<button class="district-hit" data-spot="${sp[0]}" style="left:${sp[5]}%;top:${sp[6]}%" aria-label="进入${sp[2]}"><b>${sp[1]}</b>${sp[2]}</button>`).join('')}<button class="district-hit" id="district-npc" style="left:50%;top:13%;background:#554365" aria-label="和${esc(plan.npc[0])}交谈"><b>🧑</b>${esc(plan.npc[0])}</button><div class="district-player" id="district-player" style="left:${districtPos.x}%;top:${districtPos.y}%"><svg viewBox="0 0 24 34" xmlns="http://www.w3.org/2000/svg"><rect x="6" y="0" width="12" height="6" fill="#45394f"/><rect x="4" y="6" width="16" height="11" fill="#ecc19b"/><rect x="6" y="10" width="3" height="3" fill="#26334a"/><rect x="15" y="10" width="3" height="3" fill="#26334a"/><rect x="3" y="17" width="18" height="10" fill="#7cc2a6"/><rect x="3" y="27" width="7" height="7" fill="#3e5388"/><rect x="14" y="27" width="7" height="7" fill="#3e5388"/></svg></div></div><div class="district-dialogue" id="district-chat" aria-live="polite"><strong>📜 ${s.jp} 街区探索</strong><p>点击建筑探索，也可以找街区居民交谈。也可以用 WASD、点击或触摸地图移动。</p></div><div class="district-utility"><div class="district-info">WASD、鼠标点击或触屏均可移动。可以进入店铺、与街上的人交谈。地图为游戏化示意，非真实导航。</div><div class="district-control"><button class="up" data-move="0,-8" aria-label="向上移动">▲</button><button class="left" data-move="-8,0" aria-label="向左移动">◀</button><button class="down" data-move="0,8" aria-label="向下移动">▼</button><button class="right" data-move="8,0" aria-label="向右移动">▶</button></div></div></section><section class="rpg-panel"><div class="rpg-section-head"><h2>🏘 街区地点一览</h2><small>普通生活与日语交谈</small></div><div class="district-spots">${plan.spots.map(sp=>`<button class="rpg-action" data-spot="${sp[0]}"><strong>${sp[1]} ${sp[2]}</strong>${sp[3]}</button>`).join('')}</div><p class="district-quest-note">进店办事消耗一次日常行动。浏览街区和查看店铺不消耗案件调查行动。</p></section></div>`;
 document.getElementById('district-back').onclick=tokyoHome;app.querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>selectSpot(b.dataset.spot));document.getElementById('district-npc').onclick=()=>{districtDialog=0;talkToNPC()};app.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{let [dx,dy]=b.dataset.move.split(',').map(Number);moveDistrict(dx,dy)});const dw=document.getElementById('district-world');dw.onclick=e=>{if(e.target.closest('button'))return;const r=dw.getBoundingClientRect();districtPos.x=Math.max(10,Math.min(90,(e.clientX-r.left)*100/r.width));districtPos.y=Math.max(12,Math.min(88,(e.clientY-r.top)*100/r.height));renderDistrictPosition();const near=plan.spots.find(sp=>Math.abs(sp[5]-districtPos.x)<12&&Math.abs(sp[6]-districtPos.y)<12);if(near)selectSpot(near[0])};window.scrollTo(0,0);
}
document.addEventListener('keydown',e=>{if(!district||!document.getElementById('district-world')||/input|textarea|select/i.test(document.activeElement?.tagName||''))return;let dir={ArrowUp:[0,-8],ArrowDown:[0,8],ArrowLeft:[-8,0],ArrowRight:[8,0],w:[0,-8],s:[0,8],a:[-8,0],d:[8,0],W:[0,-8],S:[0,8],A:[-8,0],D:[8,0]}[e.key];if(dir){e.preventDefault();moveDistrict(...dir)}});

const originalHome=home;
home=tokyoHome;
const oldStart=start;
start=function(id){if(!activeStation)activeStation=id==='all'?'综合挑战':(typeof sc==='function'&&sc(id)?sc(id).n:'街区挑战');oldStart(id)};
const oldShow=show;
show=function(){oldShow();let q=st.list[st.i];if(!q)return;let hud=document.createElement('div');hud.className='rpg-battle-hud';let life=100*Math.max(.1,1-(st.i/Math.max(1,st.list.length)));hud.innerHTML=`<div class="rpg-kicker">BATTLE // ${activeStation||'TOKYO'}</div><div class="rpg-battle-grid"><strong>🟦 ことばモンスター</strong><b>QUEST ${st.i+1}/${st.list.length}</b></div><div class="rpg-life"><i style="width:${life}%"></i></div><div class="rpg-monster" aria-hidden="true">👾</div><div class="rpg-battle-grid"><span>⚔️ ${V51.languageLabel()}</span><span>理解度 ${V51.language().xp}</span></div>`;app.insertBefore(hud,app.firstChild);let back=app.querySelector('.quiz-home');if(back)back.textContent='← 东京地图';};
const oldPick=pick;
pick=function(k){if(st.ans)return;let q=st.list[st.i],isCorrect=k===q.a;oldPick(k);if(V51ADD.reviewing())return;if(isCorrect){JLPT.gain(null,'district');progress.correct++}else{progress.wrong++}save();const hud=app.querySelector('.rpg-battle-hud');if(hud){let el=document.createElement('div');el.className='rpg-tiny';el.style.color=isCorrect?'#a9e5b7':'#f9b1ac';el.textContent=isCorrect?'✨ 攻撃成功！ 理解度 +'+GAME_CONFIG.jlpt.gains.district+'':'🩹 怪物的攻击！这道题已记录';hud.appendChild(el)}};
const oldEnd=end;
end=function(){oldEnd();let el=document.createElement('div');el.className='rpg-victory';el.innerHTML=`<h2>🏆 QUEST CLEAR</h2><p>本次答对 ${st.score} / ${st.list.length} 题 · 理解度 ${V51.language().xp}</p><button class="rpg-action primary" id="rpg-go-map" style="width:100%">🗺 返回东京冒险地图</button>`;app.insertBefore(el,app.firstChild);document.getElementById('rpg-go-map').onclick=tokyoHome;if(district){let ret=document.createElement('button');ret.className='rpg-action';ret.style.width='100%';ret.style.marginTop='9px';ret.textContent='🏘 返回 '+district.jp+' 像素街区';ret.onclick=()=>renderDistrict();el.appendChild(ret)};};
// First-time spawn selection and selectable regional portals.
const spawnKey='tokyo-quest-birthplace-v1';
let birth='';try{birth=localStorage.getItem(spawnKey)||''}catch(e){}
function spawnScreen(change){app.innerHTML=`<div class="rpg-shell"><section class="rpg-panel rpg-hero"><div class="rpg-kicker">NEW GAME // ARRIVAL IN JAPAN</div><h1 class="rpg-title">日本へようこそ！</h1><p>选择你的冒险出生点。选择开始冒险的机场；已获得的理解度和学习记录不会清空。</p><div class="spawn-grid"><button class="spawn-card" data-birth="haneda"><span class="spawn-icon">🛬</span><strong>羽田空港 / HND</strong><span>距东京市区较近 · 机场交通与入境任务</span><em>▶ 在羽田开始冒险</em></button><button class="spawn-card" data-birth="narita"><span class="spawn-icon">✈️</span><strong>成田空港 / NRT</strong><span>千叶县 · 机场特急与行李任务</span><em>▶ 在成田开始冒险</em></button></div>${change?'<button class="rpg-inline-back" id="spawn-cancel" style="margin-top:12px">← 返回东京地图</button>':''}</section></div>`;
 app.querySelectorAll('[data-birth]').forEach(b=>b.onclick=()=>{birth=b.dataset.birth;try{localStorage.setItem(spawnKey,birth)}catch(e){}enterDistrict(birth)});
 let cancel=app.querySelector('#spawn-cancel');if(cancel)cancel.onclick=tokyoHome;window.scrollTo(0,0);
}
/* ==== engine/survival/20-survival-core.js ==== */
/* 【生存模式核心：存档 campaign、HUD、新游戏设置、资源增减、规则怪谈随机事件】 */
/* Survival campaign: original vocabulary engine is preserved. */
const campaignKey='tokyo-survival-campaign-v1';
let campaign=null;try{campaign=JSON.parse(localStorage.getItem(campaignKey)||'null');if(campaign){campaign.photography??={version:1,photos:[]};campaign.cityVisits??={calls:{},seen:{},notes:{}};campaign.shibuyaWalk??={room:'plaza',x:2,y:8}}}catch(e){}
if(campaign && !Number.isFinite(campaign.san)){campaign.san=GAME_CONFIG.player.maxSAN;campaignSave()}
const SAN_WRONG_LOSS=5;
if(campaign){campaign.restDay ??= 0;campaign.shrineDay ??= 0;campaign.npcDay ??= 0;campaign.potions ??= 0;}
function sanClamp(n){return Math.max(0,Math.min(GAME_CONFIG.player.maxSAN,Math.round(n)))}
function sanAtmosphere(){document.body.classList.toggle('san-low',!!campaign&&campaign.san<=40);document.body.classList.toggle('san-critical',!!campaign&&campaign.san<=15)}
function sanAdjust(amount,reason){if(!campaign||(campaign.san<=0&&amount<=0))return;if(amount<0&&window.V52)amount=V52.sanScale(amount,reason);campaign.san=sanClamp(campaign.san+amount);campaignSave();sanAtmosphere();app.querySelectorAll('.survival-hud').forEach(el=>el.outerHTML=campaignHUD());if(campaign.san<=0)showMadnessEnding(reason)}
function showMadnessEnding(reason){if(!campaign||campaign.san>0||app.querySelector('#san-ending'))return;const el=document.createElement('section');el.id='san-ending';el.className='san-ending survival-box';el.innerHTML='<div class="rpg-kicker">BAD END // THE GAZE</div><h2>☾ 理智崩溃 · SAN 0</h2><p>天空中的巨眼终于与你对视。东京所有的广播同时喊出了你的名字。</p><p>你无法分辨电车鸣笛与深海的呼唤。生存挑战宣告失败。</p><p class="san-small">'+esc(reason||'克苏鲁的凝视')+'</p><button class="survival-btn" id="san-reborn">↻ 重新创建角色</button>';app.prepend(el);el.querySelector('#san-reborn').onclick=setupCampaign;window.scrollTo({top:0,behavior:'smooth'})}

const durations=GAME_CONFIG.modes;
const origins=GAME_CONFIG.character.origins; // 出身选项在 config/game.json 的 character.origins
const challenges=GAME_DATA.d["events/rules-horror"];
function campaignSave(){if(campaign){window.CASEQUEST?.sync(campaign);campaign.photography??={version:1,photos:[]};campaign.cityVisits??={calls:{},seen:{},notes:{}};campaign.shibuyaWalk??={room:'plaza',x:2,y:8}}try{localStorage.setItem(campaignKey,JSON.stringify(campaign))}catch(e){}}
function campaignHUD(){if(!campaign)return '';sanAtmosphere();let day=Math.min(campaign.day,campaign.days);return `<div class="survival-hud">☠️ 极恶东京生存之战 · DAY <b>${day}/${campaign.days}</b> · ${campaign.mode}<br>❤️ 疲劳点 ${campaign.hp}/${GAME_CONFIG.player.maxHP}　💴 ${campaign.cash.toLocaleString('ja-JP')}円　🧠 压力 ${campaign.stress}/${GAME_CONFIG.player.maxStress}　<span class="san-number">◉ SAN ${campaign.san ?? GAME_CONFIG.player.maxSAN}/${GAME_CONFIG.player.maxSAN}</span><div class="san-meter" role="progressbar" aria-label="理智值" aria-valuenow="${campaign.san ?? GAME_CONFIG.player.maxSAN}" aria-valuemin="0" aria-valuemax="${GAME_CONFIG.player.maxSAN}"><i style="width:${Math.round((campaign.san ?? GAME_CONFIG.player.maxSAN)/GAME_CONFIG.player.maxSAN*100)}%"></i></div><div class="survival-meter"><i style="width:${Math.round(campaign.hp/GAME_CONFIG.player.maxHP*100)}%"></i></div><span style="font-size:12px;color:#b8c9e7">${campaign.gender} / ${campaign.origin} · 出生：${campaign.birth==='haneda'?'羽田':'成田'}　 · 已通过 ${campaign.clears} 场挑战</span></div>`}
function updateCampaignUI(){let root=app.querySelector('.rpg-shell');if(!root||!campaign)return;if(!app.querySelector('.survival-hud'))root.insertAdjacentHTML('afterbegin',campaignHUD());if(campaign.hp<=0||campaign.cash<=0||(campaign.stress>=GAME_CONFIG.player.maxStress&&!!campaign.v52?.stressOut)||campaign.san<=0){root.insertAdjacentHTML('afterbegin','<section class="survival-box"><h2>☠ GAME OVER — 东京吞噬了你</h2><p>资源耗尽。角色存档仍在，你可以重新开启生存挑战。</p><button class="survival-btn" id="survival-restart">重新开始</button></section>');app.querySelector('#survival-restart').onclick=setupCampaign;}}
function alterCampaign(delta){if(!campaign)return;campaign.hp=Math.max(0,Math.min(GAME_CONFIG.player.maxHP,campaign.hp-(delta.hp||0)));campaign.stress=Math.max(0,Math.min(GAME_CONFIG.player.maxStress,campaign.stress+(delta.stress||0)));campaign.cash=Math.max(0,campaign.cash-(delta.cash||0));campaignSave()}
function survivalEvent(){if(!campaign)return;const e=challenges[Math.floor(Math.random()*challenges.length)];let el=app.querySelector('#survival-event');if(!el){let root=app.querySelector('.rpg-shell');if(!root)return;root.insertAdjacentHTML('afterbegin','<section class="survival-box survival-event" id="survival-event"></section>');el=app.querySelector('#survival-event')};el.innerHTML=`<div class="rpg-kicker">TOKYO RULES HORROR // RANDOM ENCOUNTER</div><h2>${e.title}</h2><p>${e.scene}</p><button class="survival-btn" data-e="bad">☠ ${e.a}</button><button class="survival-btn alt" data-e="good">▶ ${e.b}</button>`;el.querySelectorAll('[data-e]').forEach(b=>b.onclick=()=>{let good=b.dataset.e==='good';alterCampaign(good?e.reward:e.penalty);el.innerHTML=`<h2>${good?'✓ 生存成功':'✕ 规则怪谈发动'}</h2><p>${e.lesson}</p><p>${good?'正确判断，压力得到缓解。':'你的 疲劳点、压力或钱包受到影响。'}</p><button class="survival-btn" id="survival-next">继续探索</button>`;el.querySelector('#survival-next').onclick=()=>{el.remove();renderDistrict()};let old=app.querySelector('.survival-hud');if(old)old.outerHTML=campaignHUD()})}
const baseDistrictRender=renderDistrict;
renderDistrict=function(){baseDistrictRender();if(!campaign)return;let root=app.querySelector('.rpg-shell');root.insertAdjacentHTML('afterbegin',campaignHUD());let toolbox=app.querySelector('.district-utility');if(toolbox){toolbox.insertAdjacentHTML('beforeend','<div class="survival-box"><strong>☎ 东京规则怪谈</strong><p class="survival-tip">沿途可能触发公共礼仪、迷路、垃圾分类等荒诞事件。</p><button class="survival-btn" id="phone-event">📞 手机突然响了！</button><button class="survival-btn alt" id="random-event">🎲 遭遇随机事件</button></div>');toolbox.querySelector('#phone-event').onclick=()=>{const e=challenges[0];const originalRandom=Math.random;try{Math.random=()=>0;survivalEvent()}finally{Math.random=originalRandom}};toolbox.querySelector('#random-event').onclick=survivalEvent;}};
const baseMap=tokyoHome;
tokyoHome=function(){baseMap();if(window.CASE5&&CASE5.canCloseEarly()){const r=app.querySelector('.rpg-shell');if(r&&!r.querySelector('#case-close-early')){r.insertAdjacentHTML('afterbegin','<section class="survival-box" id="case-close-early"><strong>📁 FILE NO. 001 · 延期调查中</strong><p class="survival-tip">'+esc(CASE5.label())+'。查清楚了就可以随时结案。</p><button class="survival-btn" id="case-close-btn">📝 提交最终调查报告</button></section>');r.querySelector('#case-close-btn').onclick=()=>CASE5.closeEarly()}}if(!campaign)return;let root=app.querySelector('.rpg-shell');if(!root)return;root.insertAdjacentHTML('afterbegin',campaignHUD());let hero=app.querySelector('.rpg-title');if(hero)hero.innerHTML='極悪東京<br>生存之战';let t=app.querySelector('.rpg-kicker');if(t)t.textContent='TOKYO SURVIVAL // 16-BIT RULES HORROR';let nav=app.querySelector('.rpg-nav');if(nav){nav.insertAdjacentHTML('beforeend','<button id="survival-profile">☠ 生存档案</button>');nav.querySelector('#survival-profile').onclick=survivalStatus}}
function survivalStatus(){if(!campaign){setupCampaign();return}app.innerHTML=`<div class="rpg-shell"><section class="rpg-panel"><h1>☠ 生存档案</h1>${campaignHUD()}<p>主线目标：在东京坚持 ${campaign.days} 天。每天 3 次行动，夜间手动结算。日语答错只扣 疲劳点；违反规则才会扣 SAN。</p><p>角色外观：${campaign.gender} · 出身：${campaign.origin}。身份不会直接决定人物属性；关卡与遭遇事件决定难度。</p><p>${V51.languageLabel()} · 理解度 ${V51.language().xp}　✅ 战斗完成：${campaign.clears}</p><button class="survival-btn" id="survival-map">返回东京地图</button><button class="survival-btn alt" id="survival-reset">创建新角色</button></section></div>`;app.querySelector('#survival-map').onclick=tokyoHome;app.querySelector('#survival-reset').onclick=setupCampaign}
const baseEndSurvival=end;
end=function(){if(campaign){campaign.clears++;if(st.wrong.length)alterCampaign({hp:Math.min(GAME_CONFIG.wrongAnswer.quizHpMaxPerBattle,st.wrong.length*GAME_CONFIG.wrongAnswer.quizHpPerWrong),stress:Math.min(GAME_CONFIG.wrongAnswer.quizStressMaxPerBattle,st.wrong.length*GAME_CONFIG.wrongAnswer.quizStressPerWrong)});campaignSave();sanAtmosphere()}baseEndSurvival();let shell=app.querySelector('.rpg-victory');if(shell&&campaign){shell.insertAdjacentHTML('afterbegin',campaignHUD());shell.insertAdjacentHTML('beforeend','<p>这段对话结束了。时间不会自动推进，请返回东京地图进行夜间结算。</p>')}};
function setupCampaign(){let form={days:30,gender:'男性',origin:'中国',birth:'haneda'};function render(){app.innerHTML=`<div id="survival-setup" class="rpg-shell"><section class="rpg-panel rpg-hero"><div class="rpg-kicker">NEW GAME · TOKYO RULES HORROR</div><h1 class="rpg-title">极恶东京<br>生存之战</h1><p>☾ 东京被古老的克苏鲁凝视。城市居民受到深海低语侵染，逐渐变得充满敌意。你必须在诡异规则、日语试炼和失控理智之间求生。</p><p class="survival-tip">SAN 初始 100 · 只有违反东京规则才扣 SAN · 睡眠/神社/药剂/特殊 NPC 可以恢复理智</p></section><section class="survival-box"><h2>01 / 选择生存期限</h2><div class="survival-grid">${durations.map(x=>`<button class="survival-choice" data-days="${x.days}" aria-pressed="${form.days===x.days}"><strong>${x.label} · ${x.difficulty}</strong><small>初始资金 ${x.cash.toLocaleString()}円</small></button>`).join('')}</div></section><section class="survival-box"><h2>02 / 创建你的角色</h2><p>外观</p><div class="survival-grid">${['男性','女性','其他 / 自定义'].map(g=>`<button class="survival-choice" data-gender="${g}" aria-pressed="${form.gender===g}"><strong>${g}</strong></button>`).join('')}</div><p>出身背景（影响人物背景和 NPC 台词，不预设能力高低）</p><select class="survival-select" id="survival-origin">${origins.map(o=>`<option value="${o}" ${o===form.origin?'selected':''}>${o}</option>`).join('')}</select><p class="survival-tip">不同出身背景可能遇到不同的人与对话。难度由生存期限决定。</p></section><section class="survival-box"><h2>03 / 机场出生点</h2><div class="survival-grid"><button class="survival-choice" data-birth-choice="haneda" aria-pressed="${form.birth==='haneda'}"><strong>✈ 羽田机场</strong><small>京急 / 单轨</small></button><button class="survival-choice" data-birth-choice="narita" ${GAME_CONFIG.start.portChoice?'':'disabled title="第二章完成后开放"'} aria-pressed="${form.birth==='narita'}"><strong>✈ 成田机场</strong><small>Skyliner / N’EX</small></button></div><button class="survival-btn" id="survival-start" style="width:100%;margin-top:18px">▶ 开始东京生存</button></section></div>`;app.querySelectorAll('[data-days]').forEach(b=>b.onclick=()=>{form.days=+b.dataset.days;render()});app.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{form.gender=b.dataset.gender;render()});app.querySelector('#survival-origin').onchange=e=>form.origin=e.target.value;app.querySelectorAll('[data-birth-choice]').forEach(b=>b.onclick=()=>{form.birth=b.dataset.birthChoice;render()});app.querySelector('#survival-start').onclick=()=>{let mode=durations.find(x=>x.days===form.days);campaign={...form,jlpt:{level:5,xp:0},mode:mode.difficulty,day:1,hp:GAME_CONFIG.player.maxHP,cash:mode.cash,stress:GAME_CONFIG.player.startStress,san:GAME_CONFIG.player.maxSAN,clears:0};campaignSave();sanAtmosphere();birth=form.birth;try{localStorage.setItem(spawnKey,birth)}catch(e){}enterDistrict(birth)};window.scrollTo(0,0)}render()}
// The villain's line is deliberately framed as prejudice, not language advice.
/* V5 原「答错必定出现偏见 NPC」已迁移到 V16 NpcTaunts（文件末尾独立 <script>），按概率触发。 */
/* ==== engine/survival/30-recovery.js ==== */
/* 【恢复设施：休息、神社、药剂、抵抗组织暗号】 */
/* V7 — Recovery rooms. All costs, rewards and cooldowns live on the campaign save. */
