/* ==== engine/survival/40-daily-cycle.js ==== */
/* 【每日行动次数、侵染程度、打工、夜间结算】 */
/* V9 — constrained daytime actions and nightly settlement. */
function dayDefaults(){if(!campaign)return;campaign.actionDay??=campaign.day;campaign.actions??=GAME_CONFIG.day.actionsPerDay;campaign.visitedToday??=[];campaign.workedToday??=0;campaign.ruleViolations??=0;if(campaign.actionDay!==campaign.day){campaign.actionDay=campaign.day;campaign.actions=GAME_CONFIG.day.actionsPerDay;campaign.visitedToday=[];campaign.workedToday=0;} }
function infection(){return campaign?Math.min(100,Math.round((Math.max(0,campaign.day-1)/Math.max(1,campaign.days-1))*100*GAME_CONFIG.infection.speed)):0}
function invasionStage(){let x=infection(),t=GAME_CONFIG.infection.stageThresholds;return x>=t[2]?3:x>=t[1]?2:x>=t[0]?1:0}
const invasionNames=['低语初现','电波失真','深海侵染','终末凝视'];
function spendAction(type){if(!campaign)return false;dayDefaults();if(campaign.hp<=0||campaign.san<=0||campaign.cash<=0)return false;if(campaign.actions<=0){alert('今日行动点已用尽。请返回地图，进行夜间结算。');return false}if(!V51.action(type))return false;campaign.actions--;campaignSave();return true}
const dailyStart=start;
start=function(id){if(campaign&&!spendAction('study'))return;dailyStart(id)};
const dailyDistrict=enterDistrict;
enterDistrict=function(id){if(campaign){dayDefaults();if(!campaign.visitedToday.includes(id)){const fare=GAME_CONFIG.travel.districtFirstVisitFare;if(fare>0&&campaign.cash<fare){alert('交通费不足（需要 '+fare+'円）。');return}if(!spendAction('explore'))return;if(fare>0)campaign.cash-=fare;campaign.visitedToday.push(id);campaignSave()}}dailyDistrict(id)};
const dailyRecovery=recoveryAction;
recoveryAction=function(type){if(type==='sleep'&&campaign){dayDefaults();if(campaign.restDay!==campaign.day&&!spendAction('rest'))return}dailyRecovery(type)};
function nightlyClose(){if(!campaign)return;dayDefaults();if(campaign.day>=campaign.days){app.innerHTML='<div class="rpg-shell"><section class="survival-box"><h1>🏆 SURVIVED TOKYO</h1><p>你坚持了 '+campaign.days+' 天。东京仍被凝视，但你活了下来。</p>'+campaignHUD()+'<button class="survival-btn" id="end-map">返回地图</button></section></div>';app.querySelector('#end-map').onclick=tokyoHome;return}const closingDay=campaign.day;CH1FIX.beginNight();GS.change({cash:-nightlyCost()},'夜间生活费'+(caseLodgingActive()?'（住宿由委托方承担）':''));GS.change({stress:Math.max(0,GAME_CONFIG.day.nightStressBase-campaign.actions)},'夜间压力（基础值减剩余行动点）');V51.sleep();CH1FIX.closeNight(closingDay);campaign.day++;campaign.actionDay=campaign.day;campaign.actions=GAME_CONFIG.day.actionsPerDay;campaign.visitedToday=[];campaign.workedToday=0;campaignSave();queueMicrotask(()=>CH1FIX.showNight());sanAtmosphere();if(campaign.cash<=0||(campaign.stress>=GAME_CONFIG.player.maxStress&&!!campaign.v52?.stressOut)||campaign.hp<=0||campaign.san<=0){survivalStatus();return}if(campaign.day>campaign.days){survivalStatus();return}tokyoHome()}
function workShift(){if(!campaign||campaign.konbini?.shift)return;const stage=invasionStage(),wk=GAME_CONFIG.work,base=Math.max(wk.minIncome,wk.baseIncome-wk.incomeDropPerStage*stage),wage=campaign.konbini?.wages?.[base]??base;if(!(wage>0)||!spendAction('work'))return;campaign.cash+=wage;campaign.workedToday=(campaign.workedToday||0)+1;campaign.stress=Math.min(GAME_CONFIG.player.maxStress,campaign.stress+wk.stressBase+stage*wk.stressPerStage);campaignSave();tokyoHome();alert('快速打工结束。本次工资 '+wage+' 円。')}
const priorSurvivalEvent=survivalEvent;
survivalEvent=function(){if(!campaign)return;const stage=invasionStage();let list=challenges;const e=list[Math.floor(Math.random()*list.length)];let el=app.querySelector('#survival-event');if(!el){let root=app.querySelector('.rpg-shell');if(!root)return;root.insertAdjacentHTML('afterbegin','<section class="survival-box survival-event" id="survival-event"></section>');el=app.querySelector('#survival-event')}
const threats=['车厢广播传来低语。','人群的目光一瞬间停在你身上。','站牌文字似乎在缓慢蠕动。','整座车站的影子正向你靠拢。'];
el.innerHTML='<div class="rpg-kicker">RULES HORROR'+(V52.eroShown()?' // 浸蚀 '+['','Ⅰ','Ⅱ','Ⅲ','Ⅳ'][V52.eroStage()]:'')+'</div><h2>'+e.title+'</h2><p>'+threats[stage]+' '+e.scene+'</p><button class="survival-btn" data-e="bad">☠ '+e.a+'</button><button class="survival-btn alt" data-e="good">▶ '+e.b+'</button>';
el.querySelectorAll('[data-e]').forEach(b=>b.onclick=()=>{let good=b.dataset.e==='good';alterCampaign(good?e.reward:e.penalty);if(!good){campaign.ruleViolations++;sanAdjust(-(GAME_CONFIG.sanRules.ruleViolationBase+stage*GAME_CONFIG.sanRules.ruleViolationPerStage),'违反东京规则：'+e.title)}else{campaign.stress=Math.max(0,campaign.stress-2)}campaignSave();el.innerHTML='<h2>'+(good?'✓ 暂时避开凝视':'✕ 规则怪谈发动')+'</h2><p>'+e.lesson+'</p><p>'+(good?'SAN 不变。':'SAN -'+(GAME_CONFIG.sanRules.ruleViolationBase+stage*GAME_CONFIG.sanRules.ruleViolationPerStage)+'，规则违规会损伤理智。')+'</p><button class="survival-btn" id="survival-next">继续探索</button>';el.querySelector('#survival-next').onclick=()=>{el.remove();renderDistrict()};app.querySelectorAll('.survival-hud').forEach(x=>x.outerHTML=campaignHUD())})};
function dayPanel(){if(!campaign)return '';dayDefaults();return `<section class="survival-box daily-panel"><div class="rpg-kicker">DAY ${campaign.day} / ${campaign.days}</div><h2>东京生存日程</h2><p>☀ 剩余行动 ${campaign.actions}/${GAME_CONFIG.day.actionsPerDay}</p><p class="survival-tip">打工、在店里用日语办事、首次探索新街区、旅馆休息各消耗 1 次行动。规则违规才扣 SAN。每夜支付 ${nightlyCost()}円 生活费；压力随消耗的行动略微增长。</p><div class="daily-buttons">${campaign.firstDayComplete&&campaign.day>=2?'<button class="survival-btn alt" id="daily-hotel">'+((()=>{try{const m=TM.now();return m>=18*60||m<6*60}catch(e){return false}})()?'🏨 回酒店（夜间调查）':'🏨 白天回酒店看看')+'</button>':''}<button class="survival-btn alt" id="daily-night">☾ 夜间结算 / 下一天</button></div><p class="survival-tip">办事：在街区的店里用日语和人打交道。探索：首次进入某街区消耗行动。休息：前往旅馆。</p></section>`}
function attachDayPanel(){if(!campaign)return;let root=app.querySelector('.rpg-shell');if(!root)return;root.querySelectorAll('.daily-panel').forEach(el=>el.remove());root.insertAdjacentHTML('afterbegin',dayPanel());let w=root.querySelector('#daily-work'),n=root.querySelector('#daily-night');if(w)w.onclick=workShift;if(n)n.onclick=nightlyClose;const dh=root.querySelector('#daily-hotel');if(dh)dh.onclick=()=>{if(window.HOTEL_DAY2)HOTEL_DAY2.open();};document.body.dataset.invasion=String(invasionStage());}
const dailyMap=tokyoHome;
tokyoHome=function(){dailyMap();attachDayPanel()};
const dailyDistrictRender=renderDistrict;
renderDistrict=function(){dailyDistrictRender();attachDayPanel();let npc=app.querySelector('.district-utility .survival-box strong');if(npc&&V52.eroStage()>=2)npc.textContent='☠ 東京の異形'};
const dailyStatus=survivalStatus;
survivalStatus=function(){dailyStatus();attachDayPanel()};
const dailySetup=setupCampaign;
setupCampaign=function(){dailySetup();const tip=app.querySelector('#survival-setup .survival-tip');if(tip)tip.textContent='SAN 初始'+GAME_CONFIG.player.maxSAN+'；仅违反东京生存规则才降低。日语答错扣 疲劳点。每日三次行动，夜间支付生活费；越接近通关，侵染越严重。'};
