  for(let i=0;i<4;i++){px(T+8,T+14+i*12,4*T-16,3,'#b9a77a');for(let k=0;k<9;k++)px(T+10+k*13,T+8+i*12,8,6,['#e06a5a','#5aa0e0','#f0c040','#70c080','#c070c0'][(k+i)%5])}
