  P(g,226,56,60,86,'#c0402e');P(g,230,60,52,78,'#d4553c');P(g,226,56,60,6,'#2b2226');P(g,226,136,60,6,'#2b2226');
  g.fillStyle='#2b1a16';g.font='bold 18px DotGothic16, serif';g.fillText('観',246,94);g.fillText('音',246,120);
