  for(let i=0;i<5;i++){g.fillStyle='#d9cdb2';g.fillRect(180+i*25,213+(i%2)*9,21,15);g.fillStyle='#817363';g.fillRect(183+i*25,217+(i%2)*9,14,1);g.fillRect(183+i*25,222+(i%2)*9,12,1)}
