  return e.text.split(/\r?\n\s*\r?\n/).map(t=>t.startsWith('你将她母亲的捐款记录')?(materials.length===3?t:materials.length?'你将'+materials.join('、')+'摆在她面前。':'你将报告推到她面前。'):t);
