/* Chapter 01: guide, never force. Keep all investigation gates, time limits, and saves unchanged. */
(function(){
 function shouldRemind(){
  if(!campaign||campaign.day===1||!campaign.firstDayComplete||campaign.storyIndex!==0)return false;
  if(campaign.hotelCase&&campaign.hotelCase.ending)return false;
  const c=campaign.case1;
  if(c&&['closed','submitted','due','report','dead'].includes(c.state))return false;
  if(window.H18&&H18.active())return false;
  const v=campaign.hotelCase&&campaign.hotelCase.v18;
  return !(v&&v.clockDay===campaign.day&&v.flags&&v.flags['tonight:entered']);
 }
 const mapBeforeReminder=tokyoHome;
 tokyoHome=function(){
  mapBeforeReminder.apply(this,arguments);
  if(!shouldRemind())return;
  const shell=app&&app.querySelector('.rpg-shell');
  if(!shell||shell.querySelector('#ch1-night-reminder'))return;
  const panel=document.createElement('section');
  panel.className='survival-box';
  panel.id='ch1-night-reminder';
  panel.style.border='1px solid #c49b55';
  panel.innerHTML='<div class="rpg-kicker">CASE NO. 001 · 今晚的主线</div><h2>🌙 别忘了回酒店调查</h2><p>白天可以探索东京，傍晚记得回品川港屋酒店继续调查207号室。每晚都有有限的调查时间，直接跳到下一天可能漏掉线索。</p><button type="button" class="survival-btn" id="ch1-night-go">🏨 回酒店调查 →</button><p class="survival-tip">也可点底部「任务」→「追踪当前主线」。回酒店将结束今天剩余的白天行动。</p>';
  const daily=shell.querySelector('.daily-panel');
  if(daily)daily.insertAdjacentElement('afterend',panel);
  else shell.insertAdjacentElement('afterbegin',panel);
  const btn=panel.querySelector('#ch1-night-go');
  if(btn)btn.onclick=()=>storyQuest();
 };
 const originalClose=nightlyClose;
 nightlyClose=function(){
  if(!shouldRemind())return originalClose.apply(this,arguments);
  const args=arguments,that=this;
  UI.modal({
   title:'🌙 今晚还没有回酒店调查',
   text:'207号室的调查每晚都有时间窗口。现在直接结算，可能错过今晚的线索、证言和调查进度。\n\n建议先回港屋酒店调查，再结束这一天。',
   buttons:[
    {label:'🏨 先回酒店调查',primary:true,fn:()=>storyQuest()},
    {label:'仍然跳过今晚',fn:()=>originalClose.apply(that,args)},
    {label:'取消，继续白天行动'}
   ]
  });
 };
})();
/* ==== engine/addons/98a-map-location-shortcuts.js ==== */
/* World map shortcuts: go home via existing train rules; reopen current district without teleport. */
(function(){
 const homeId='shinagawa';
 const prevHome=tokyoHome;
 tokyoHome=function(){
  prevHome.apply(this,arguments);
  if(!campaign||!campaign.firstDayComplete)return;
  const map=app&&app.querySelector('#map-host');
  if(!map||app.querySelector('#et-map-shortcuts'))return;
  const here=TRAVEL.where();
  if(!here||!byId[here])return;
  const home=byId[homeId],current=byId[here];
  const panel=document.createElement('div');
  panel.id='et-map-shortcuts';
  panel.setAttribute('aria-label','大地图快捷位置');
  panel.innerHTML='<div class="et-loc-shortcut-heading">📍 目前所在：<strong></strong>　·　🏠 居住地：品川港屋酒店</div>'+
   '<div class="et-loc-shortcut-buttons">'+
   '<button type="button" class="rpg-action" id="et-map-home-shortcut">🏠 回居住地（品川）</button>'+
   '<button type="button" class="rpg-action" id="et-map-here-shortcut">📍 返回当前位置</button></div>'+
   '<p class="et-loc-shortcut-note">回居住地使用正常乘车流程；当前位置返回当前街区，不另收车费。</p>';
  panel.querySelector('strong').textContent=current.jp;
  map.insertAdjacentElement('beforebegin',panel);
  // This is a real return to the station/area, not a free teleport across districts.
  function atCurrent(id){
   if(id!==TRAVEL.where()){TRAVEL.plan(id);return}
   dayDefaults();
   // New day resets visitedToday, but re-entering the district where the player
   // already stands must not charge an extra action or repeat a first-visit fare.
   if(!campaign.visitedToday.includes(id)){
    campaign.visitedToday.push(id);
    campaignSave();
   }
   enterDistrict(id);
  }
  panel.querySelector('#et-map-home-shortcut').onclick=function(){
   if(TRAVEL.where()===homeId){atCurrent(homeId);return}
   TRAVEL.plan(homeId);
  };
  panel.querySelector('#et-map-here-shortcut').onclick=function(){atCurrent(here)};
  // Location markers follow saved station state; never modify the selected station.
  const svg=app.querySelector('.tokyo-svg');
  if(svg){
   const ns='http://www.w3.org/2000/svg';
   function ring(id,cls,colour,radius){const st=byId[id];if(!st)return;
    const circle=document.createElementNS(ns,'circle');
    circle.setAttribute('cx',st.x);circle.setAttribute('cy',st.y);circle.setAttribute('r',radius);
    circle.setAttribute('fill','none');circle.setAttribute('stroke',colour);
    circle.setAttribute('stroke-width','2.5');circle.setAttribute('pointer-events','none');
    circle.setAttribute('class',cls);svg.appendChild(circle);
   }
   ring(homeId,'et-location-home','#dfbd77',12);
   ring(here,'et-location-current','#92e6d4',17);
  }
 };
 const css=document.createElement('style');css.textContent=`
  #et-map-shortcuts{border:1px solid #7798af;background:rgba(9,23,42,.75);border-radius:5px;padding:12px;margin:10px 0 14px;display:grid;gap:9px;color:#f0e9d7}
  .et-loc-shortcut-heading{font-size:13px;line-height:1.5}
  .et-loc-shortcut-buttons{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
  #et-map-shortcuts button{min-width:0;min-height:45px;white-space:normal;padding:10px 6px;font-size:13px}
  .et-loc-shortcut-note{font-size:11px;color:#c1cedc;margin:0;line-height:1.5}
  @media(max-width:380px){.et-loc-shortcut-buttons{grid-template-columns:1fr}}
 `;document.head.appendChild(css);
})();
/* ==== engine/survival/99-startup.js ==== */
/* 【生存模式启动（必须是 survival 文件夹里最后一个文件）】 */
/* ==== 大地图视口记忆：离开后返回原滚动位置 ==== */
(function(){
  const state={visited:false,y:0,mapX:0,mapY:0};
  let rendering=false;
  function mapHost(){return document.getElementById('map-host')}
  function remember(){
    const host=mapHost();
    if(!host||rendering)return;
    state.visited=true;
    state.y=window.scrollY||document.documentElement.scrollTop||0;
    state.mapX=host.scrollLeft||0;
    state.mapY=host.scrollTop||0;
  }
  // 元素被替换前的点击记录：兼容底部导航、车站和场景入口。
  document.addEventListener('click',function(){if(mapHost())remember()},true);
  window.addEventListener('scroll',function(){if(mapHost()&&!rendering)remember()},{passive:true});
  document.addEventListener('scroll',function(e){if(e.target&&e.target.id==='map-host'&&!rendering)remember()},true);
  const originalHome=tokyoHome;
  tokyoHome=function(){
    const wasOnMap=!!mapHost();
    if(wasOnMap)remember();
    const restore=state.visited;
    const y=state.y,x=state.mapX,mapY=state.mapY;
    rendering=true;
    try{return originalHome.apply(this,arguments)}
    finally{
      // 原首页内部会强制 window.scrollTo(0,0)，因此在它完成绘制后恢复。
      const host=mapHost();
      if(host&&restore){
        host.scrollLeft=x;
        host.scrollTop=mapY;
        window.scrollTo({top:y,left:0,behavior:'instant'});
      }
      requestAnimationFrame(function(){
        const h=mapHost();
        if(h&&restore){
          h.scrollLeft=x;
          h.scrollTop=mapY;
          window.scrollTo({top:y,left:0,behavior:'instant'});
        }
        rendering=false;
        if(h)remember();
      });
    }
  };
})();
