  const o=s.cur;shell.classList.toggle('kbs-pay',!!(o&&o.phase==='pay'&&o.pay&&o.pay.status!=='ok'));shell.classList.toggle('kbs-talk',!!(o&&o.phase==='talk'));shell.classList.toggle('kbs-wet',!!(o&&o.wet));
