   const html=lines.slice(-2).map((l,i,a)=>`<p class="${i===a.length-1?'last':''}"><span lang="ja">${esc(l.jp)}</span>${l.zh?`<small>${esc(l.zh)}</small>`:''}</p>`).join('');
   if(html!==lastBub){lastBub=html;bub.innerHTML=html}
